{
  "nl": {
    "issue": [
      {
        "text": "物业服务合同的界定、物业服务人与业主的主要义务，以及合同终止后的后合同义务",
        "rules": [
          "c937-def",
          "c937-2",
          "c941-1",
          "c942-1",
          "c943",
          "c944-1",
          "c949-1a",
          "c950-1"
        ]
      }
    ],
    "conditions": [
      {
        "text": "物业服务人在物业服务区域内为业主提供建筑物及其附属设施的维修养护、环境卫生和相关秩序的管理维护等服务，业主支付物业费",
        "rules": [
          "c937-def"
        ]
      },
      {
        "text": "物业服务人包括物业服务企业和其他管理人",
        "rules": [
          "c937-2"
        ]
      },
      {
        "text": "前期物业服务合同约定的服务期限届满前，业主委员会或者业主与新物业服务人订立的物业服务合同生效",
        "rules": [
          "c940"
        ]
      },
      {
        "text": "业主违反约定逾期不支付物业费",
        "rules": [
          "c944-2a"
        ]
      },
      {
        "text": "业主依照法定程序共同决定解聘物业服务人",
        "rules": [
          "c946-1"
        ]
      },
      {
        "text": "物业服务期限届满后，业主没有依法作出续聘或者另聘物业服务人的决定，物业服务人继续提供物业服务",
        "rules": [
          "c948-1"
        ]
      },
      {
        "text": "物业服务合同终止后，业主或者业主大会选聘的新物业服务人或者决定自行管理的业主尚未接管",
        "rules": [
          "c950-1"
        ]
      }
    ],
    "exceptions": [
      {
        "text": "决定解聘应当提前六十日书面通知物业服务人，但合同对通知期限另有约定的除外",
        "rules": [
          "c946-2"
        ]
      },
      {
        "text": "解除合同造成物业服务人损失的，除不可归责于业主的事由外，业主应当赔偿损失",
        "rules": [
          "c946-3"
        ]
      },
      {
        "text": "不定期物业服务合同当事人可以随时解除，但应当提前六十日书面通知对方（合同对通知期限另有约定的除外）",
        "rules": [
          "c948-2",
          "c948-3"
        ]
      }
    ],
    "effects": [
      {
        "text": "前期物业服务合同约定的服务期限届满前，业主委员会或者业主与新物业服务人订立的物业服务合同生效的，前期物业服务合同终止",
        "rules": [
          "c940"
        ]
      },
      {
        "text": "物业服务人将部分专项服务事项委托给专业性服务组织或者其他第三人的，应当就该部分专项服务事项向业主负责",
        "rules": [
          "c941-1"
        ]
      },
      {
        "text": "物业服务人不得将全部物业服务转委托给第三人，或者将全部物业服务支解后分别转委托给第三人",
        "rules": [
          "c941-2"
        ]
      },
      {
        "text": "物业服务人应当按照约定和物业的使用性质妥善维修、养护、清洁、绿化和经营管理业主共有部分，维护基本秩序，采取合理措施保护业主的人身、财产安全",
        "rules": [
          "c942-1"
        ]
      },
      {
        "text": "对物业服务区域内违反治安、环保、消防等法律法规的行为，物业服务人应当及时采取合理措施制止、向有关行政主管部门报告并协助处理",
        "rules": [
          "c942-2"
        ]
      },
      {
        "text": "物业服务人应当定期将服务事项、负责人员、质量要求、收费项目、收费标准、履行情况以及维修资金使用情况、共有部分经营与收益情况等以合理方式向业主公开并向业主大会、业主委员会报告",
        "rules": [
          "c943"
        ]
      },
      {
        "text": "业主应当按照约定向物业服务人支付物业费",
        "rules": [
          "c944-1"
        ]
      },
      {
        "text": "物业服务人已按照约定和有关规定提供服务的，业主不得以未接受或者无需接受相关物业服务为由拒绝支付物业费",
        "rules": [
          "c944-1b"
        ]
      },
      {
        "text": "业主逾期不支付物业费的，物业服务人可以催告其在合理期限内支付；合理期限届满仍不支付的，可以提起诉讼或者申请仲裁",
        "rules": [
          "c944-2a",
          "c944-2b"
        ]
      },
      {
        "text": "物业服务人不得采取停止供电、供水、供热、供燃气等方式催交物业费",
        "rules": [
          "c944-3"
        ]
      },
      {
        "text": "业主装饰装修房屋的，应当事先告知物业服务人、遵守其提示的合理注意事项并配合必要的现场检查",
        "rules": [
          "c945-1"
        ]
      },
      {
        "text": "业主转让、出租物业专有部分、设立居住权或者依法改变共有部分用途的，应当及时将相关情况告知物业服务人",
        "rules": [
          "c945-2"
        ]
      },
      {
        "text": "业主依照法定程序共同决定解聘物业服务人的，可以解除物业服务合同；决定解聘的应当提前六十日书面通知，造成物业服务人损失的应当赔偿",
        "rules": [
          "c946-1",
          "c946-2",
          "c946-3"
        ]
      },
      {
        "text": "物业服务期限届满后业主未作续聘或另聘决定而物业服务人继续服务的，原物业服务合同继续有效但服务期限为不定期；当事人可以随时解除，但应当提前六十日书面通知对方",
        "rules": [
          "c948-1",
          "c948-2",
          "c948-3"
        ]
      },
      {
        "text": "物业服务合同终止的，原物业服务人应当在约定期限或者合理期限内退出物业服务区域，交还物业服务用房、相关设施和必需资料，配合新物业服务人交接并如实告知物业的使用和管理状况",
        "rules": [
          "c949-1a",
          "c949-1b"
        ]
      },
      {
        "text": "原物业服务人违反退出、交还与交接义务的，不得请求业主支付物业服务合同终止后的物业费；造成业主损失的，应当赔偿损失",
        "rules": [
          "c949-2a",
          "c949-2b"
        ]
      },
      {
        "text": "物业服务合同终止后，在新物业服务人或者决定自行管理的业主接管之前，原物业服务人应当继续处理物业服务事项，并可以请求业主支付该期间的物业费",
        "rules": [
          "c950-1",
          "c950-2"
        ]
      }
    ],
    "priority": [
      {
        "text": "物业服务人已按约定和有关规定提供服务的，业主不得以未接受或者无需接受相关物业服务为由拒付物业费，排除其相应抗辩",
        "rules": [
          "c944-1b"
        ]
      },
      {
        "text": "即使业主欠费，物业服务人也不得以停止供电、供水、供热、供燃气等方式催交物业费",
        "rules": [
          "c944-3"
        ]
      },
      {
        "text": "原物业服务人依第950条继续处理物业服务事项的，可以请求该期间的物业费，构成第949条第2款“不得请求终止后物业费”的例外",
        "rules": [
          "c950-2",
          "c949-2a"
        ]
      },
      {
        "text": "解聘与不定期合同解除的通知期限，合同另有约定的优先于六十日的法定通知期限",
        "rules": [
          "c946-2",
          "c948-3"
        ]
      },
      {
        "text": "不定期物业服务合同当事人可随时解除，属特别规定，不受第946条业主共同决定解聘程序的限制",
        "rules": [
          "c948-2",
          "c946-1"
        ]
      }
    ],
    "distinguish": [
      {
        "text": "LEGO 卡片称物业服务合同以持续性劳务为标的，不同于承揽合同（以完成特定工作成果为目的）与租赁合同（转移占有、以使用收益为核心），属学理区分，法条未作规定",
        "rules": []
      },
      {
        "text": "笔记将本节列为2020年新增的典型合同（第十六节）；第947条（续聘、另聘）未挂载，本卡片不涉及",
        "rules": []
      },
      {
        "text": "LEGO 卡片称物业服务人未履行报告义务“可能影响其收费权利”，法条未作此规定，不予采纳",
        "rules": []
      },
      {
        "text": "第937条第2款将“其他管理人”一并纳入物业服务人，与第941条以下义务主体范围一致",
        "rules": [
          "c937-2"
        ]
      }
    ]
  },
